+@* A single Kanban column displaying its header, task cards, and an optional add-task form *@
+
+<div class="col">
+    <div class="card h-100">
+        <div class="card-header d-flex justify-content-between align-items-center">
+            <strong>@ColumnName</strong>
+            <span class="badge bg-secondary">@Tasks.Count</span>
+        </div>
+        <div class="card-body overflow-auto" style="max-height: 65vh;">
+            @foreach (var task in Tasks)
+            {
+                <TaskCard Task="task"
+                          CanMoveLeft="CanMoveLeft"
+                          CanMoveRight="CanMoveRight"
+                          OnMoveLeft="() => OnMoveTask.InvokeAsync((task.Id, MoveDirection.Left))"
+                          OnMoveRight="() => OnMoveTask.InvokeAsync((task.Id, MoveDirection.Right))" />
+            }
+
+            @if (ShowForm)
+            {
+                <AddTaskForm OnSave="HandleTaskCreated" OnCancel="() => ShowForm = false" />
+            }
+        </div>
+        <div class="card-footer">
+            <button class="btn btn-outline-primary btn-sm w-100" @onclick="() => ShowForm = true" disabled="@ShowForm">
+                + Add Task
+            </button>
+        </div>
+    </div>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
+    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = [];
+    [Parameter] public bool CanMoveLeft { get; set; }
+    [Parameter] public bool CanMoveRight { get; set; }
+    [Parameter] public EventCallback<(int TaskId, MoveDirection Direction)> OnMoveTask { get; set; }
+    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }
+
+    private bool ShowForm { get; set; }
+
+    private async Task HandleTaskCreated((string Title, string Assignee, string Priority, DateTime DueDate) data)
+    {
+        await OnTaskCreated.InvokeAsync(data);
+        ShowForm = false;
+    }
+
+    public enum MoveDirection { Left, Right }
+}
+

